<section class="card"><h2>Staff documents</h2><form method="post" enctype="multipart/form-data"><?php hr_fields('upload_document',$id,$version);?><div class="grid"><?php hr_catalogue_select('Document type','type_id',$catalogue['document'],'',true);?><label class="hr-field">Choose file *<input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png" required><small>PDF, JPG or PNG · maximum 5 MB. Documents are private and downloaded only after permission checks.</small></label></div><p><button>Add document</button></p></form><?php if($can('hr.settings')):?><p><a href="<?=access_h(access_url('hr-settings.php?section=documents'))?>">Manage document types in Settings</a></p><?php endif?><div class="scroll"><table><thead><tr><th>Document</th><th>Type</th><th>Recorded</th><th></th></tr></thead><tbody><?php foreach($documents as $doc):?><tr><td><?=access_h($doc['filename'])?><br><small><?=(int)$doc['size_bytes']?> bytes</small></td><td><?=access_h($doc['type_name'] ?? $doc['name'] ?? '')?></td><td><?=access_h(display_date($doc['created_at']))?> UTC</td><td><a href="<?=access_h(access_url('hr-document.php?id='.(int)$doc['id']))?>">Download</a></td></tr><?php endforeach?><?php if(!$documents):?><tr><td colspan="4">No documents uploaded. Supporting copies are optional for onboarding.</td></tr><?php endif?></tbody></table></div></section>
